/* Daya Clothing 3.0. Interfaz operativa conectada exclusivamente a la API del servidor. */
(()=>{'use strict';
const $=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mx=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(n||0),date=f=>new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'short',year:'numeric'}).format(new Date(f+'T12:00:00'));
const icon=(n,cls='')=>`<img class="icon ${cls}" src="/Dayas/gestion/assets/icons/${n}.svg" alt="" aria-hidden="true">`,brand=()=>`<a class="brand" href="#inicio" aria-label="Daya Clothing, inicio"><img class="brand-mark" src="../assets/daya-mark.svg" alt=""><div><img class="brand-wordmark" src="../assets/daya-wordmark.svg" alt=""><small>Gestión de tu boutique</small></div></a>`;
let inventoryView='list',stockFilter='all',dialogReturnFocus=null;
let db=Daya.empty(),user=null,csrf='',revision=0,sample=false,review=false,smtp=false,cart=[],category='Todas',query='',saleFilter='Todas',reportFrom=Daya.date().slice(0,8)+'01',reportTo=Daya.date(),cashDate=Daya.date(),photoValue='',busy=false,setupRequired=false,pendingRequest=null;
const imageFor=p=>p?.foto||(sample?'/Dayas/gestion/assets/'+(['Cuidado facial'].includes(p?.cat)?'cuidado':['Perfumería'].includes(p?.cat)?'perfume':['Maquillaje'].includes(p?.cat)?'maquillaje':['Accesorios'].includes(p?.cat)?'joyeria':'moda')+'.jpg':'');
const today=()=>Daya.date(),owner=()=>user?.rol==='d',route=()=>location.hash.slice(1)||'inicio',cid=id=>db.daya_clientes.find(c=>c.id===id),pid=id=>db.daya_productos.find(p=>p.id===id),sale=id=>db.daya_ventas.find(v=>v.id===id),customer=v=>cid(v.cid)?.nombre||'Mostrador',folio=v=>'#'+String(v.folio).padStart(4,'0'),qty=p=>p.v.reduce((s,v)=>s+v.s,0),reserved=p=>p.v.reduce((s,v)=>s+v.ap,0),sum=xs=>Daya.money(xs.reduce((s,n)=>s+n,0)),pending=()=>db.daya_ventas.filter(v=>v.estado==='Pendiente'),initials=n=>String(n).trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
function toast(m){$('#toast').textContent=m;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...options.headers}});const b=await r.json();if(!r.ok){if(r.status===401&&user){user=null;csrf='';cart=[];authView(false);throw Error('Tu sesión terminó. Inicia sesión de nuevo.');}if(r.status===409&&user){await refresh();}const err=Error(b.error||b.message||'No se pudo completar la operación.');err.status=r.status;throw err;}return b;}
async function refresh(){if(review)return;const r=await api('/api/state');db=r.data;revision=r.revision;user=r.user;sample=r.sample;}
async function operation(name,args){if(review)throw Error('Esta vista es de lectura. Inicia la aplicación para guardar operaciones.');const signature=JSON.stringify([name,args]);if(!pendingRequest||pendingRequest.signature!==signature)pendingRequest={signature,id:crypto.randomUUID(),revision};try{const r=await api('/api/operation',{method:'POST',body:JSON.stringify({operation:name,args,revision:pendingRequest.revision,requestId:pendingRequest.id})});await refresh();pendingRequest=null;return r.result;}catch(err){if(err.status)pendingRequest=null;throw err;}}
const badge=v=>`<span class="badge ${v.estado==='Liquidado'?'success':v.limite&&v.limite<today()&&v.estado==='Pendiente'?'danger':''}">${e(v.estado==='Pendiente'&&v.limite&&v.limite<today()?'Vencido':v.estado)}</span>`;
const linkButton=(url,label,ico='plus',type='')=>`<a class="button ${type}" href="${e(url)}">${icon(ico)}${e(label)}</a>`;
const button=(act,label,ico='',id='',type='primary')=>`<button class="${type}" data-act="${act}" data-id="${e(id)}">${ico?icon(ico):''}${e(label)}</button>`;
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${e(label)}</span><input name="${e(name)}" type="${type}" value="${e(value)}" ${extra}></label>`;
const select=(label,name,options,value='')=>`<label class="field"><span>${e(label)}</span><select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`;}).join('')}</select></label>`;
const methods=()=>select('Método de pago','met',Daya.MET);
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${e(title)}</h1>${sub?`<p>${e(sub)}</p>`:''}</div><div class="actions">${actions}</div></div>`;}
function stat(label,value,note='',accent=false){return `<div class="stat"><span>${e(label)}</span><strong class="${accent?'accent':''}">${e(value)}</strong><small>${e(note)}</small></div>`;}
function empty(title,text,action=''){return `<div class="empty"><h2>${e(title)}</h2><p>${e(text)}</p>${action}</div>`;}
function formFooter(label='Guardar'){return `<div class="form-error" role="alert"></div><div class="form-footer"><button class="secondary button" type="button" data-act="close">Volver</button><button class="primary" type="submit">${e(label)}</button></div>`;}
function modal(title,content){const m=$('#modal');if(!m.open)dialogReturnFocus=document.activeElement;m.innerHTML=`<button class="close-dialog" data-act="close" aria-label="Cerrar ventana">${icon('x')}</button><h2 id="modal-title">${e(title)}</h2>${content}`;m.setAttribute('aria-labelledby','modal-title');if(!m.open)m.showModal();const first=m.querySelector('input:not([type=hidden]),select,textarea');if(first&&!first.matches('[type=file]'))first.focus({preventScroll:true});}
function close(){if($('#modal').open)$('#modal').close();}
$('#modal').addEventListener('close',()=>{if($('#modal').open)return;if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus({preventScroll:true});dialogReturnFocus=null;});
const NAV=[['inicio','home','Inicio'],['inventario','package','Inventario'],['vender','shopping-bag','Nueva venta'],['ventas','receipt','Ventas y tickets'],['cobranza','wallet','Cobranza'],['clientes','users','Clientes'],['reportes','chart-bar','Reportes'],['caja','wallet','Caja'],['catalogo','shopping-bag','Catálogo'],['solicitudes','mail','Solicitudes web'],['ajustes','settings','Ajustes']];
function connectionText(){return review?'Revisión · Solo lectura':navigator.onLine?'Sesión en línea':'Sin conexión';}
function updateConnection(){const el=$('.connection');if(el){el.textContent=connectionText();el.classList.toggle('offline',!navigator.onLine);}}
function labelTables(){document.querySelectorAll('.table-wrap table').forEach(table=>{table.setAttribute('role','table');table.querySelector('thead')?.setAttribute('role','rowgroup');table.querySelector('tbody')?.setAttribute('role','rowgroup');table.querySelectorAll('tr').forEach(row=>row.setAttribute('role','row'));const heads=[...table.querySelectorAll('thead th')].map(th=>{th.scope='col';th.setAttribute('role','columnheader');return th.textContent;});table.querySelectorAll('tbody tr').forEach(row=>[...row.cells].forEach((cell,i)=>{cell.dataset.label=heads[i]||'';cell.setAttribute('role','cell');}));});}
function renderKeepingFocus(){const active=document.activeElement,act=active?.dataset.act,id=active?.dataset.id;render();if(act)[...document.querySelectorAll('[data-act]')].find(el=>el.dataset.act===act&&el.dataset.id===id)?.focus({preventScroll:true});}
function shell(content){const current=route().split('/')[0],nav=NAV.filter(x=>owner()||['cobranza','catalogo','ventas'].includes(x[0])),mobile=owner()?[['inicio','home','Inicio'],['inventario','package','Inventario'],['vender','plus','Vender'],['cobranza','wallet','Cobranza'],['mas','dots','Más']]:[['cobranza','wallet','Cobranza'],['catalogo','shopping-bag','Catálogo'],['ventas','receipt','Tickets'],['mas','dots','Más']],mobileCurrent=mobile.some(x=>x[0]===current)?current:'mas';$('#app').innerHTML=`<aside class="sidebar">${brand()}<nav class="nav" aria-label="Navegación principal">${nav.map(([r,i,l],idx)=>`${idx===6?'<div class="nav-gap"></div>':''}<a href="#${r}" class="${current===r?'active':''}" ${current===r?'aria-current="page"':''}>${icon(i)}<span>${l}</span>${r==='cobranza'&&pending().length?`<span class="count">${pending().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-footer"><div class="sidebar-links"><a href="/Dayas/tienda.html">Ver tienda ↗</a><a href="/Dayas/studio.html">Studio local ↗</a></div><div class="account"><div class="avatar" aria-hidden="true">${icon('users')}</div><div class="account-copy"><strong>${e(user.nombre)}</strong><small>${owner()?'Dueña':'Vendedora'}</small></div><button data-act="logout" aria-label="Cerrar sesión">${icon('logout')}</button></div></div></aside><div class="workspace"><header class="topbar"><a class="top-brand" href="#inicio" aria-label="Daya Clothing, inicio"><img src="../assets/daya-mark.svg" alt=""></a><span class="top-context">Tu boutique / Gestión</span><button class="search-trigger" data-act="search" aria-haspopup="dialog" aria-keyshortcuts="Control+k Meta+k">${icon('search')}<span>Buscar productos, clientas o tickets</span><kbd aria-hidden="true">${/Mac|iPhone|iPad/.test(navigator.platform)?'⌘':'Ctrl'} K</kbd></button><div class="top-actions"><span class="connection ${navigator.onLine?'':'offline'}" role="status">${connectionText()}</span><a href="#cobranza" class="icon-button" aria-label="Ver cuentas pendientes">${icon('bell')}</a></div></header><main class="main" id="main" tabindex="-1">${sample?`<div class="sample-note"><span>${review?'<strong>Solo lectura.</strong> ':''}Colección de ejemplo · Personas y operaciones ficticias</span><a href="${review?'/Dayas/gestion/':'#ajustes'}">${review?'Abrir mi tienda ↗':'Mi tienda'}</a></div>`:''}${content}<footer class="footer"><span>${e(date(today()))} · MXN</span><span>${review?'Datos ficticios · Solo lectura':'Daya Clothing · Gestión de tu boutique'}</span></footer></main></div><nav class="bottom-nav ${owner()?'':'seller'}" aria-label="Navegación móvil">${mobile.map(([r,i,l])=>`<a href="#${r}" class="${r==='vender'?'sell ':''}${mobileCurrent===r?'active':''}" ${mobileCurrent===r?'aria-current="page"':''}>${icon(i)}${l}</a>`).join('')}</nav>`;labelTables();}

function chart(){const days=Array.from({length:7},(_,i)=>{const x=new Date();x.setDate(x.getDate()-6+i);const f=`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;return {f,n:Daya.periodSummary(db,f,f).cobrado,label:new Intl.DateTimeFormat('es-MX',{weekday:'short'}).format(x)};});const max=Math.max(1,...days.map(x=>x.n));return `<div class="chart" role="img" aria-label="Cobros de los últimos siete días: ${e(days.map(x=>x.label+' '+mx(x.n)).join(', '))}">${days.map(x=>`<div class="chart-col" title="${e(date(x.f)+' · '+mx(x.n))}"><div class="chart-bar" style="height:${Math.max(2,x.n/max*100)}%"></div><span>${e(x.label)}</span></div>`).join('')}</div><div class="chart-legend"><span>Últimos 7 días</span><strong>${mx(sum(days.map(x=>x.n)))} cobrados</strong></div>`;}
function debtRow(v){const isLate=v.limite&&v.limite<today();return `<a class="row-item" href="#ticket/${e(v.id)}"><div class="avatar">${e(initials(customer(v)))}</div><div class="grow"><strong>${e(customer(v))}</strong><small>${e(folio(v))} · ${v.limite?`Límite ${e(date(v.limite))}`:'Sin fecha límite'}</small></div><div class="end"><strong class="money">${mx(Daya.balance(v))}</strong><small class="${isLate?'danger-text':''}">${isLate?'Vencido':'Pendiente'}</small></div>${icon('chevron-right')}</a>`;}
function dashboard(){const current=db.daya_ventas.filter(v=>v.fecha===today()&&v.estado!=='Cancelado'),p=Daya.periodSummary(db,today(),today()),low=db.daya_productos.filter(p=>qty(p)<=p.min),late=pending().filter(v=>v.limite&&v.limite<today()),rank=rankProducts(db.daya_ventas.filter(v=>v.estado!=='Cancelado'));return pageHead('Hola, '+user.nombre.split(' ')[0]+'.','Tu boutique, al día. Todo lo que necesitas para vender con calma.',linkButton('#vender','Nueva venta'))+`<div class="stats">${stat('Vendido hoy',mx(sum(current.map(Daya.total))),current.length+' ventas registradas')}${stat('Cobrado hoy',mx(p.cobrado),'Todos los métodos de pago',true)}${stat('Por cobrar',mx(sum(pending().map(Daya.balance))),pending().length+' cuentas pendientes')}${stat('Flujo de hoy',mx(p.neto),'Ingresos menos egresos')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><h2>Así va tu semana</h2><a href="#reportes">Ver reportes</a></div>${chart()}</section><section class="section"><div class="panel-head"><h2>Próximos cobros</h2><a href="#cobranza">Ver ${pending().length} cuentas</a></div><div class="panel">${pending().length?pending().slice().sort((a,b)=>(a.limite||'9999').localeCompare(b.limite||'9999')).slice(0,4).map(debtRow).join(''):empty('Todo al día','No hay saldos pendientes.')}</div></section></div><aside class="dashboard-aside"><section class="quick-start"><p class="eyebrow">Hecho para tu día a día</p><h2>Tu siguiente paso,<br>más sencillo.</h2><p>De la primera venta al cierre de caja. Tu boutique, en orden.</p><div class="quick-links"><a href="#vender">${icon('shopping-bag')}Registrar una venta${icon('chevron-right')}</a><a href="#caja">${icon('wallet')}Revisar la caja de hoy${icon('chevron-right')}</a><a href="#catalogo">${icon('package')}Consultar el catálogo${icon('chevron-right')}</a></div></section><section class="section panel"><div class="panel-head"><h2>Para atender hoy</h2></div><a class="row-item" href="#cobranza"><span class="grow"><strong>${late.length} cuentas vencidas</strong><small>Consulta saldos y últimos avisos</small></span>${icon('chevron-right')}</a><a class="row-item" href="#inventario"><span class="grow"><strong>${low.length} productos por reponer</strong><small>Disponibles iguales o menores al mínimo</small></span>${icon('chevron-right')}</a><div class="row-item"><span class="grow"><strong>${rank[0]?e(rank[0].name):'Tu próximo favorito'}</strong><small>${rank[0]?'El más vendido · '+rank[0].q+' piezas':'Registra una venta para ver tendencias'}</small></span>${icon('shopping-bag')}</div></section></aside></div>`;}
function filterToolbar(placeholder='Buscar por nombre, código o marca…'){const cats=['Todas',...new Set(db.daya_productos.map(p=>p.cat).filter(Boolean))];if(!cats.includes(category))category='Todas';return `<div class="toolbar"><div class="chips">${cats.map(c=>`<button class="chip ${category===c?'active':''}" aria-pressed="${category===c}" data-act="category" data-id="${e(c)}">${e(c)}</button>`).join('')}</div><div class="search-field">${icon('search')}<input id="product-search" type="search" placeholder="${e(placeholder)}" aria-label="Buscar productos" value="${e(query)}"></div></div>`;}
function productCards(mode='inventory'){const list=db.daya_productos.filter(p=>(category==='Todas'||p.cat===category)&&[p.nombre,p.sku,p.brand,p.cat].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase())&&(mode!=='catalog'||qty(p)>0)&&(mode!=='inventory'||stockFilter==='all'||stockFilter==='available'&&qty(p)>0||stockFilter==='low'&&qty(p)<=p.min||stockFilter==='empty'&&qty(p)===0));if(!list.length)return empty('Sin productos en esta vista','Prueba otra búsqueda, categoría o filtro de existencias.',owner()&&mode==='inventory'?button('product-new','Agregar producto','plus'):'');return `<p class="product-results help" role="status">${list.length} ${list.length===1?'producto':'productos'}${mode==='inventory'?' · Disponibles para vender y piezas apartadas':''}</p><div class="${mode==='inventory'&&inventoryView==='list'?'inventory-list':'product-grid'}">${list.map(p=>`<article class="product">${imageFor(p)?`<img class="product-photo" src="${e(imageFor(p))}" alt="${e(p.nombre)}" loading="lazy">`:`<div class="product-photo loading">${icon('package')}</div>`}${qty(p)<=p.min?`<span class="badge ${qty(p)===0?'danger':''}">${qty(p)===0?'Agotado':'Stock bajo'}</span>`:''}<div class="product-info"><small>${e(p.brand||p.cat||'Daya Clothing')} · ${e(p.sku)}</small><h3 title="${e(p.nombre)}">${e(p.nombre)}</h3><div class="product-line"><strong class="product-price money">${mx(p.precio)}</strong><span class="product-stock">${qty(p)} disponibles${mode==='inventory'&&reserved(p)?' · '+reserved(p)+' apartadas':''}</span></div><div class="product-actions">${mode==='pos'?`<button class="primary" data-act="cart-add" data-id="${e(p.id)}" ${!qty(p)?'disabled':''}>Agregar</button>`:mode==='catalog'?button('want','Lo quiero','brand-whatsapp',p.id,'secondary button'):button('product-edit','Ver producto','',p.id,'secondary button')}</div></div></article>`).join('')}</div>`;}
function inventory(){const cost=sum(db.daya_productos.map(p=>p.costo*(qty(p)+reserved(p)))),value=sum(db.daya_productos.map(p=>p.precio*(qty(p)+reserved(p))));return pageHead('Tu inventario','Cada talla, tono y favorito en su lugar.',button('product-new','Agregar producto','plus'))+`<div class="stats">${stat('Productos',String(db.daya_productos.length),'Ropa y belleza')}${stat('Disponibles',String(sum(db.daya_productos.map(qty))),'Piezas listas para vender')}${stat('Valor a costo',mx(cost),'Incluye piezas apartadas')}${stat('Valor de venta',mx(value),'Precio actual de inventario')}</div>${filterToolbar()}<div class="inventory-controls"><label class="field"><span>Existencias</span><select id="stock-filter"><option value="all" ${stockFilter==='all'?'selected':''}>Todos los productos</option><option value="available" ${stockFilter==='available'?'selected':''}>Disponibles</option><option value="low" ${stockFilter==='low'?'selected':''}>Stock bajo y agotados</option><option value="empty" ${stockFilter==='empty'?'selected':''}>Agotados</option></select></label><div class="view-switch" role="group" aria-label="Vista del inventario"><button data-act="inventory-view" data-id="list" aria-pressed="${inventoryView==='list'}">Lista</button><button data-act="inventory-view" data-id="grid" aria-pressed="${inventoryView==='grid'}">Cuadrícula</button></div></div><div id="products">${productCards()}</div><details class="details section"><summary>Historial de movimientos</summary><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Variante</th><th>Movimiento</th><th>Piezas</th></tr></thead><tbody>${db.daya_movs.slice(-60).reverse().map(m=>`<tr><td>${e(date(m.f))}</td><td>${e(m.pn)}</td><td>${e(m.var)}</td><td>${e(m.tp)}<small class="muted"> · ${e(m.mo)}</small></td><td>${m.q}</td></tr>`).join('')}</tbody></table></div></details>`;}
function cartView(){return `<h2>Tu venta</h2><p class="help">${cart.reduce((s,i)=>s+i.q,0)} piezas seleccionadas</p><div class="cart-list">${cart.length?cart.map((i,n)=>{const p=pid(i.pid),v=p?.v[i.vi];return `<div class="cart-item">${imageFor(p)?`<img src="${e(imageFor(p))}" alt="">`:''}<div class="grow"><strong>${e(p?.nombre||i.d)}</strong><small>${e([v?.t,v?.c].filter(Boolean).join(' / '))} · ${mx(i.p)}</small><div class="stepper"><button data-act="cart-minus" data-id="${n}" aria-label="Quitar una pieza de ${e(p?.nombre)}">${icon('minus')}</button><span>${i.q}</span><button data-act="cart-plus" data-id="${n}" aria-label="Agregar una pieza de ${e(p?.nombre)}">${icon('plus')}</button></div></div><strong class="money">${mx(i.p*i.q)}</strong></div>`;}).join(''):'<p class="help">Selecciona productos para comenzar. Elige la talla o tono al agregarlos.</p>'}</div><form class="form" id="sale-form">${select('Clienta','cid',[['','Mostrador'],...db.daya_clientes.map(c=>[c.id,c.nombre])])}<button type="button" class="button quiet" data-act="client-new">+ Agregar clienta</button><div class="fields">${select('Tipo de venta','tipo',[['contado','Contado'],['apartado','Apartado']])}${field('Descuento (MXN)','desc',0,'number','min="0" step="0.01"')}</div><div id="installment-fields" class="fields hide">${field('Primer abono (MXN)','enganche',0,'number','min="0" step="0.01"')}${field('Fecha límite','limite','','date')}</div>${methods()}<div class="cart-total"><span>Total</span><strong id="cart-total">${mx(sum(cart.map(i=>i.p*i.q)))}</strong></div><div class="form-error" role="alert"></div><button class="primary full" ${!cart.length?'disabled':''}>${icon('shopping-bag')}Registrar venta</button><p class="help">El inventario se actualiza al guardar. En apartado, las piezas se reservan hasta entregar.</p></form>`;}
function restoreCartFields(values){const form=$('#sale-form');if(!values||!form)return;Object.entries(values).forEach(([name,value])=>{const control=form.elements.namedItem(name);if(control)control.value=value;});$('#installment-fields').classList.toggle('hide',values.tipo!=='apartado');$('#cart-total').textContent=mx(Math.max(0,sum(cart.map(i=>i.p*i.q))-Number(values.desc||0)));}
function renderCart(){const current=$('#sale-form'),values=current?Object.fromEntries(new FormData(current)):null;$('#cart').innerHTML=cartView();restoreCartFields(values);updateCartJump();}
function updateCartJump(){const jump=$('.cart-jump');if(jump)jump.innerHTML=`<span>Tu venta · ${cart.reduce((n,i)=>n+i.q,0)} piezas</span><strong>Revisar venta ↓</strong>`;}

function pos(){return pageHead('Una venta más.','Selecciona sus favoritos y elige cómo va a pagar.',linkButton('#ventas','Ver ventas','receipt','secondary'))+`<div class="pos"><section><a class="cart-jump" href="#cart" data-act="cart-jump"><span>Tu venta · ${cart.reduce((n,i)=>n+i.q,0)} piezas</span><strong>Revisar venta ↓</strong></a>${filterToolbar()}<div id="products">${productCards('pos')}</div></section><aside class="cart" id="cart">${cartView()}</aside></div>`;}
function sales(){let list=db.daya_ventas.slice().reverse();if(saleFilter!=='Todas')list=list.filter(v=>v.estado===saleFilter);return pageHead('Ventas y tickets','Contado, apartados y el detalle de cada pago.',owner()?linkButton('#vender','Nueva venta'):'')+`<div class="toolbar"><div class="chips">${['Todas','Pendiente','Liquidado','Cancelado'].map(x=>`<button class="chip ${saleFilter===x?'active':''}" aria-pressed="${saleFilter===x}" data-act="sale-filter" data-id="${x}">${x==='Pendiente'?'Pendientes':x==='Liquidado'?'Liquidadas':x==='Cancelado'?'Canceladas':x}</button>`).join('')}</div>${button('export','Exportar CSV','download','','secondary button')}</div><div class="panel">${list.length?list.map(v=>`<a class="row-item" href="#ticket/${e(v.id)}"><div class="avatar">${icon('receipt')}</div><div class="grow"><strong>${e(customer(v))}</strong><small>${e(folio(v))} · ${e(date(v.fecha))} · ${v.items.reduce((s,i)=>s+i.q,0)} piezas</small></div><div class="end"><strong class="money">${mx(Daya.total(v))}</strong><small>${v.estado==='Pendiente'?'Debe '+mx(Daya.balance(v)):e(v.estado)}</small></div>${icon('chevron-right')}</a>`).join(''):empty('Tu próxima venta empieza aquí','Las ventas aparecerán en este espacio.',owner()?linkButton('#vender','Nueva venta'):'')}</div>`;}
function clients(){return pageHead('Tus clientas','Conoce su historial y acompaña cada compra.',owner()?button('client-new','Agregar clienta','plus'):'')+`<div class="toolbar"><div class="search-field">${icon('search')}<input id="client-search" type="search" placeholder="Buscar clienta…" aria-label="Buscar clientas"></div><small>${db.daya_clientes.length} clientas · ${new Set(pending().map(v=>v.cid)).size} con saldo</small></div><div class="panel" id="client-list">${clientRows('')}</div>`;}
function clientRows(q){const list=db.daya_clientes.filter(c=>[c.nombre,c.tel].join(' ').toLowerCase().includes(q.toLowerCase()));return list.map(c=>{const vs=db.daya_ventas.filter(v=>v.cid===c.id),debt=sum(vs.filter(v=>v.estado==='Pendiente').map(Daya.balance));return `<a class="row-item" href="#cliente/${e(c.id)}"><div class="avatar">${e(initials(c.nombre))}</div><div class="grow"><strong>${e(c.nombre)}</strong><small>${vs.length} compras${c.tel?' · '+e(c.tel):''}</small></div>${debt?`<span class="badge danger">Debe ${mx(debt)}</span>`:icon('chevron-right')}</a>`;}).join('')||'<p class="help">No hay clientas que coincidan con tu búsqueda.</p>';}
function clientDetail(id){const c=cid(id);if(!c)return empty('Clienta no encontrada','Regresa a la lista.',linkButton('#clientes','Ver clientas','users'));const vs=db.daya_ventas.filter(v=>v.cid===id),ps=vs.filter(v=>v.estado==='Pendiente');return pageHead(c.nombre,c.tel||'Sin teléfono registrado',owner()?button('client-edit','Editar clienta','users',id,'secondary button'):'')+`<div class="stats">${stat('Compras',String(vs.length),'Historial completo')}${stat('Saldo pendiente',mx(sum(ps.map(Daya.balance))),ps.length+' cuentas')}${stat('Comprado',mx(sum(vs.filter(v=>v.estado!=='Cancelado').map(Daya.total))),'Ventas activas')}${stat('Última compra',vs.length?date(vs.at(-1).fecha):'—','')}</div><div class="panel"><h2>Historial de compras</h2>${vs.slice().reverse().map(v=>`<a class="row-item" href="#ticket/${e(v.id)}"><div class="grow"><strong>${e(folio(v))} · ${mx(Daya.total(v))}</strong><small>${e(date(v.fecha))}</small></div>${badge(v)}${icon('chevron-right')}</a>`).join('')||'<p class="help section">Todavía no tiene compras.</p>'}<p class="help section">${e(c.nota||'Sin notas.')}</p></div>`;}
function cobranza(){const late=pending().filter(v=>v.limite&&v.limite<today()),paid=sum(db.daya_ventas.flatMap(v=>v.abonos.filter(a=>!a.anulado).map(a=>a.m)));return pageHead('Cuentas por cobrar','El saldo claro. La conversación, cercana.')+`<div class="stats">${stat('Por cobrar',mx(sum(pending().map(Daya.balance))),pending().length+' cuentas pendientes',true)}${stat('Vencido',mx(sum(late.map(Daya.balance))),late.length+' cuentas por atender')}${stat('Cobrado acumulado',mx(paid),'Pagos activos registrados')}${stat('Clientas con saldo',String(new Set(pending().map(v=>v.cid||'mostrador')).size),'Sin contar cuentas canceladas')}</div><div class="panel">${pending().length?pending().slice().sort((a,b)=>(a.limite||'9999').localeCompare(b.limite||'9999')).map(v=>`<div class="details">${debtRow(v)}<div class="progress"><span style="width:${Math.min(100,Daya.paid(v)/Daya.total(v)*100)}%"></span></div><div class="actions" style="margin-top:14px"><small>${mx(Daya.paid(v))} de ${mx(Daya.total(v))} · ${db.daya_recs[v.id]?'Último aviso: '+e(date(db.daya_recs[v.id])):'Sin aviso registrado'}</small>${button('remind','Recordar por WhatsApp','brand-whatsapp',v.id,'quiet button')}</div></div>`).join(''):empty('Todo al día','No hay saldos pendientes.')}</div>`;}
function receipt(v,publicMode=false){const c=cid(v.cid);return `<article class="receipt" id="receipt"><div class="receipt-brand">${brand()}<div class="end"><strong>${e(folio(v))}</strong><small class="muted" style="display:block">${e(date(v.fecha))}</small></div></div><div class="receipt-customer"><div><small class="muted">Clienta</small><strong style="display:block">${e(c?.nombre||'Mostrador')}</strong></div>${badge(v)}</div>${v.items.map(i=>{const p=pid(i.pid);return `<div class="row-item">${imageFor(p)?`<img class="thumb" src="${e(imageFor(p))}" alt="">`:''}<div class="grow"><strong>${i.q} × ${e(i.d)}</strong><small>${e([i.t,i.c].filter(Boolean).join(' / '))} · ${mx(i.p)} c/u</small></div><strong class="money">${mx(i.p*i.q)}</strong></div>`;}).join('')}<div class="receipt-totals"><div><span>Subtotal</span><strong>${mx(Daya.total(v)+v.desc)}</strong></div><div><span>Descuento</span><strong>−${mx(v.desc)}</strong></div><div class="large"><span>Total</span><strong>${mx(Daya.total(v))}</strong></div><div><span>Total abonado</span><strong>${mx(Daya.paid(v))}</strong></div><div class="large"><span>${v.estado==='Cancelado'?'Saldo al cancelar':'Saldo pendiente'}</span><strong>${mx(Daya.balance(v))}</strong></div></div><div class="section"><h3>Historial de pagos</h3>${v.abonos.map(a=>`<div class="row-item"><div class="grow"><strong>${mx(a.m)} · ${e(a.met)}</strong><small>${e(date(a.f))}${a.anulado?' · ANULADO: '+e(a.anulado.motivo):''}</small></div>${!publicMode&&owner()&&!a.anulado&&v.estado!=='Cancelado'?`<button class="quiet button" data-act="void" data-id="${e(v.id)}" data-payment="${e(a.id)}">Anular</button>`:''}</div>`).join('')||'<p class="help">Sin abonos registrados.</p>'}</div>${v.limite?`<p class="help section">Fecha límite: ${e(date(v.limite))}</p>`:''}<p class="receipt-thanks">Gracias por elegir Daya.<br>Conserva este ticket como comprobante de tus pagos.${v.estado==='Cancelado'?'<br>Venta cancelada; historial de pagos conservado.':''}</p></article>`;}
function ticket(id){const v=sale(id);if(!v)return empty('Ticket no encontrado','La venta pudo cambiar al restaurar un respaldo.',linkButton('#ventas','Ver ventas','receipt'));return pageHead('Venta '+folio(v),customer(v)+' · '+date(v.fecha),linkButton('#ventas','Volver a ventas','receipt','secondary'))+`<div class="receipt-layout">${receipt(v)}<aside class="receipt-side"><div class="balance-card"><span>${v.estado==='Cancelado'?'Saldo histórico':'Saldo pendiente'}</span><strong>${mx(Daya.balance(v))}</strong><small>${e(v.estado)} · ${e(v.stockMode==='reservado'?'Productos reservados':v.stockMode==='entregado'?'Productos entregados':'Estado de inventario conservado')}</small></div>${v.estado==='Pendiente'?`<section class="panel"><h2>Registrar abono</h2><form id="pay-form" class="form section" data-id="${e(v.id)}">${field('Importe (MXN)','m','','number',`min="0.01" max="${Daya.balance(v)}" step="0.01" required`)}${methods()}<div class="form-error" role="alert"></div><button class="primary">Guardar abono</button></form></section>`:''}<section class="panel section"><h2>Compartir ticket</h2><div class="form section">${button('whatsapp','Enviar por WhatsApp','brand-whatsapp',v.id,'secondary button')}${button('share','Compartir detalle','arrow-up-right',v.id,'secondary button')}${select('Papel térmico','thermal',[['80','80 mm'],['58','58 mm']])}${button('print','Imprimir ticket','receipt',v.id,'secondary button')}${owner()?button('mail-ticket','Enviar copia a la tienda','mail',v.id,'quiet button'):''}</div><p class="help section">WhatsApp abre el texto para que tú lo envíes. Compartir detalle no publica la cuenta en internet.</p></section>${owner()?`<section class="section panel"><h2>Entrega y ajustes</h2><div class="form section">${v.estado==='Liquidado'&&v.stockMode==='reservado'?button('deliver','Confirmar entrega','package',v.id):''}${v.estado!=='Cancelado'?button('cancel','Cancelar venta','',v.id,'danger button'):''}</div><p class="help section">Cancelar conserva los abonos. Si devuelves dinero, registra también el egreso en Caja.</p></section>`:''}</aside></div>`;}
function rankProducts(vs){const m=new Map();for(const v of vs)for(const i of v.items){const key=i.pid||i.d,r=m.get(key)||{id:i.pid,name:i.d,q:0,m:0};r.q+=i.q;r.m+=i.q*i.p;m.set(key,r);}return [...m.values()].sort((a,b)=>b.q-a.q);}
function reports(){const vs=db.daya_ventas.filter(v=>v.estado!=='Cancelado'&&v.fecha>=reportFrom&&v.fecha<=reportTo),p=Daya.periodSummary(db,reportFrom,reportTo),r=rankProducts(vs),profit=sum(vs.map(v=>{const sub=sum(v.items.map(i=>i.p*i.q));return sum(v.items.filter(i=>i.cost!==undefined).map(i=>(i.p*(1-(sub?v.desc/sub:0))-i.cost)*i.q));})),nocost=vs.flatMap(v=>v.items).filter(i=>i.cost===undefined).reduce((s,i)=>s+i.q,0),old=db.daya_productos.filter(p=>!db.daya_movs.some(m=>m.pid===p.id&&m.f>=offset(-30)));return pageHead('Tu negocio, con claridad.','Distingue lo vendido, lo cobrado y lo que realmente se mueve.',button('export','Exportar ventas','download','','secondary button'))+`<div class="toolbar"><div class="chips">${[['day','Día'],['week','Semana'],['month','Mes'],['year','Año']].map(([id,label])=>button('period',label,'',id,'chip')).join('')}</div><div class="filter-dates">${field('Desde','report-from',reportFrom,'date')}${field('Hasta','report-to',reportTo,'date')}</div></div><div class="stats">${stat('Vendido',mx(sum(vs.map(Daya.total))),vs.length+' ventas del periodo')}${stat('Cobros del periodo',mx(p.cobrado),'Ingresos automáticos conservados')}${stat('Flujo neto',mx(p.neto),'Todos los métodos; incluye anulaciones',true)}${stat('Utilidad estimada',mx(profit),nocost?nocost+' piezas sin costo registrado':'Antes de gastos operativos')}</div><div class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>Lo más vendido</h2><span class="help">Por piezas</span></div>${r.slice(0,8).map((x,i)=>{const p=pid(x.id);return `<div class="row-item"><span class="muted">${i+1}</span>${imageFor(p)?`<img class="thumb" src="${e(imageFor(p))}" alt="">`:''}<div class="grow"><strong>${e(x.name)}</strong><small>${x.q} piezas</small></div><strong class="money">${mx(x.m)}</strong></div>`;}).join('')||'<p class="help">No hay ventas en este periodo.</p>'}</div><aside><section class="panel"><h2>Flujo por método</h2>${[['Efectivo',p.efectivo],['Transferencia',p.transferencia],['Tarjeta',p.tarjeta],['Ingresos',p.ingresos],['Egresos',p.egresos],['Anulaciones',p.anulado]].map(([k,n])=>`<div class="row-item"><span class="grow">${k}</span><strong>${mx(n)}</strong></div>`).join('')}<p class="help section">La utilidad usa costo guardado al vender y descuento proporcional. No descuenta gastos. El flujo conserva movimientos de cortes cerrados y sus contrapartidas.</p></section><section class="panel section"><h2>Sin movimiento en 30 días</h2>${old.map(p=>`<div class="row-item"><span class="grow">${e(p.nombre)}</span><strong>${qty(p)} pzas.</strong></div>`).join('')||'<p class="help section">Todo el inventario tuvo movimientos recientes.</p>'}</section></aside></div>`;}
function offset(n){const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function caja(){const s=Daya.cashSummary(db,cashDate),rows=Daya.cashRows(db,cashDate),closed=db.daya_cortes.find(c=>c.f===cashDate),ap=db.daya_aper.find(a=>a.f===cashDate);return pageHead('Caja del día','Cada entrada y salida, en su lugar.',!closed?button('cash-new','Nuevo movimiento','plus'):'')+`<div class="toolbar">${field('Fecha de consulta','cash-date',cashDate,'date')}<span class="badge ${closed?'success':''}">${closed?'Corte guardado':ap?'Caja abierta':'Sin apertura'}</span></div><div class="stats">${stat('Debe haber',mx(s.esp),'Apertura '+mx(s.ap),true)}${stat('Entradas en efectivo',mx(s.ing),'Ventas, abonos y otros ingresos')}${stat('Salidas en efectivo',mx(s.egr),'Incluye contrapartidas')}${stat('Otros métodos',mx(s.transfer+s.card),'Transferencia '+mx(s.transfer)+' · Tarjeta '+mx(s.card))}</div><div class="settings-grid"><section class="panel"><h2>Movimientos</h2>${rows.map(m=>`<div class="row-item"><div class="grow"><strong>${e(m.cat)}</strong><small>${e(m.desc)} · ${e(m.met)} · ${m.auto?'Automático':'Manual'}</small></div><strong class="money">${m.tipo==='Egreso'?'−':'+'}${mx(m.m)}</strong></div>`).join('')||'<p class="help section">Sin movimientos en esta fecha.</p>'}</section><aside><section class="panel"><h2>${closed?'Corte del día':ap?'Contar y cerrar':'Abrir caja'}</h2>${closed?`<div class="stats" style="grid-template-columns:1fr 1fr">${stat('Contado',mx(closed.con))}${stat('Diferencia',mx(closed.dif))}</div><p class="help">El corte se conserva como instantánea y no se sobrescribe.</p>`:`<form class="form section" id="${ap?'cut':'opening'}-form">${field(ap?'Efectivo contado (MXN)':'Fondo inicial (MXN)','m','','number','min="0" step="0.01" required')}<div class="form-error" role="alert"></div><button class="primary">${ap?'Revisar y guardar corte':'Guardar apertura'}</button></form>`}</section><section class="panel section"><h2>Historial de cortes</h2>${db.daya_cortes.slice().reverse().map(c=>`<div class="row-item"><div class="grow"><strong>${e(date(c.f))}</strong><small>Esperado ${mx(c.esp)} · Contado ${mx(c.con)}</small></div><strong class="money">${mx(c.dif)}</strong></div>`).join('')||'<p class="help section">Los cortes guardados aparecerán aquí.</p>'}</section></aside></div>`;}
function catalog(){return pageHead('Favoritos de Daya','Ropa, belleza y accesorios disponibles hoy.',button('share-catalog','Compartir lista','arrow-up-right','','secondary button'))+filterToolbar()+`<div id="products">${productCards('catalog')}</div>`;}
function settings(){const c=db.daya_cfg;return pageHead('Tu tienda','Información, equipo, correos y respaldos.')+`<div class="settings-grid"><section class="panel"><h2>Información de Daya</h2><form id="settings-form" class="form section">${field('Nombre de la tienda','storeName',c.storeName||'Daya Clothing','text','required maxlength="100"')}${field('Correo de la tienda','email',c.email||'','email','required')}${field('WhatsApp de la tienda','tel',c.tel||'','tel','placeholder="10 dígitos"')}<label class="field"><span>Plantilla de cobranza</span><textarea name="msg" required>${e(c.msg)}</textarea></label><p class="help">Variables: {nombre}, {saldo}, {folio}, {fecha}. Cada mensaje lo envías tú desde WhatsApp.</p><label><input type="checkbox" name="autoBackup" ${c.autoBackup?'checked':''}> Descargar respaldo al cerrar caja</label><div class="form-error" role="alert"></div><button class="primary">Guardar información</button></form></section><aside><section class="panel"><h2>Tu respaldo</h2><p class="help section">Descarga todos los datos de negocio. Las cuentas y contraseñas del servidor se administran por separado.</p><div class="form section">${button('backup','Descargar respaldo JSON','download','','secondary button')}<label class="field"><span>Restaurar respaldo compatible</span><input id="import-file" type="file" accept="application/json,.json"></label></div><p class="help section">Antes de restaurar se guarda una copia en el servidor. Solo se aceptan respaldos válidos y se conserva el acceso del equipo.</p></section><section class="panel section"><h2>Correo de la tienda</h2><p class="help section">${smtp?'Transporte SMTP configurado. Comprueba la recepción real con un envío de prueba.':'Pendiente de conectar Gmail al servidor. Las plantillas están listas; todavía no se envían mensajes.'}</p><div class="form section">${button('mail-preview','Vista previa del correo','eye','','secondary button')}${button('mail-test','Enviar correo de prueba','mail','','secondary button')}${button('mail-log','Ver estado de envíos','mail','','quiet button')}</div></section></aside></div><section class="panel section"><div class="panel-head"><h2>Tu equipo</h2>${button('user-new','Agregar persona','plus','','secondary button')}</div><div id="users-list"><p class="help">Cargando cuentas…</p></div></section><details class="details section"><summary>Historial de actividad</summary><div class="list">${db.daya_audit.slice(-35).reverse().map(a=>`<div class="row-item"><div class="grow"><strong>${e(a.acc)}</strong><small>${e(a.u)} · ${e(new Date(a.t).toLocaleString('es-MX'))}</small></div><span class="help">${e(a.det)}</span></div>`).join('')}</div></details>${!db.daya_productos.length&&!db.daya_ventas.length?`<section class="notice section"><h3>Conocer Daya con ejemplos</h3><p class="section">Carga una colección ficticia con fotografías, clientas y operaciones. Solo está disponible mientras la tienda esté vacía.</p><div class="section">${button('sample','Cargar colección de ejemplo','package','','secondary button')}</div></section>`:''}`;}
function more(){return pageHead('Tu espacio','Accesos de tu tienda.')+`<div class="panel">${NAV.filter(x=>owner()||['ventas','catalogo','cobranza'].includes(x[0])).map(([r,i,l])=>`<a class="row-item" href="#${r}">${icon(i)}<strong class="grow">${l}</strong>${icon('chevron-right')}</a>`).join('')}<a class="row-item" href="/Dayas/tienda.html">${icon('shopping-bag')}<strong class="grow">Ver tienda</strong>${icon('arrow-up-right')}</a><a class="row-item" href="/Dayas/studio.html">${icon('package')}<strong class="grow">Studio local</strong>${icon('arrow-up-right')}</a><div class="row-item">${button('logout','Cerrar sesión','logout','','secondary button')}</div></div>`;}
function webRequests(){let requests=[];try{requests=JSON.parse(localStorage.getItem('daya-web-inquiries-v1')||'[]')}catch{}return pageHead('Solicitudes de la web','Selecciones guardadas en este navegador. Confirma disponibilidad con cada clienta.')+`<div class="notice"><strong>Solicitudes de este navegador</strong><p>No se sincronizan entre dispositivos. No representan pagos ni reservan inventario.</p></div><section class="panel">${requests.length?requests.map(r=>`<article class="web-request"><h2>${e(r.id)} · ${e(r.name)}</h2><p>${e(r.email)} · ${e(r.phone)}</p><p>${e(r.note)}</p><ul>${(r.items||[]).map(i=>`<li>${e(i.name)} · ${e(i.size)} / ${e(i.color)} · ${e(i.qty)} piezas</li>`).join('')}</ul><strong>${mx(r.total)}</strong><p class="help">Sin cobro; solicitud pendiente de confirmar.</p></article>`).join(''):empty('Aún no hay solicitudes','Las selecciones de la tienda realizadas en este navegador aparecerán aquí.')}</section>`;}
function render(){if(!user)return;const currentCart=$('#sale-form'),cartValues=currentCart?Object.fromEntries(new FormData(currentCart)):null;const r=route().split('/'),allowed=['cobranza','catalogo','ventas','ticket','mas','cliente','clientes'];if(!owner()&&!allowed.includes(r[0])){location.hash='cobranza';return;}document.title=(NAV.find(n=>n[0]===r[0])?.[2]||'Daya Clothing')+' · Daya';let html;switch(r[0]){case'inicio':case'vistaprevia':html=dashboard();break;case'inventario':html=inventory();break;case'vender':html=pos();break;case'ventas':html=sales();break;case'clientes':html=clients();break;case'cliente':html=clientDetail(r[1]);break;case'cobranza':html=cobranza();break;case'ticket':html=ticket(r[1]);break;case'reportes':html=reports();break;case'caja':html=caja();break;case'catalogo':html=catalog();break;case'solicitudes':html=webRequests();break;case'ajustes':html=settings();break;case'mas':html=more();break;default:html=empty('Este enlace no está disponible','Vuelve al inicio de tu tienda.',linkButton('#inicio','Ir al inicio','home'));}shell(html);restoreCartFields(cartValues);if(r[0]==='ajustes')loadUsers();}
function productForm(id){const p=pid(id);photoValue=p?.foto||'';modal(p?'Editar producto':'Agregar producto',`<form class="form" id="product-form" data-id="${e(id||'')}">${field('Nombre del producto','nombre',p?.nombre||'','text','required maxlength="150"')}<div class="fields">${field('Categoría','cat',p?.cat||'','text','placeholder="Ropa, cuidado facial…"')}${field('Marca / colección','brand',p?.brand||'')}</div><div class="fields">${field('Código SKU','sku',p?.sku||'')}${field('Stock mínimo','min',p?.min??2,'number','min="0" step="1" required')}</div><div class="fields">${field('Costo (MXN)','costo',p?.costo||0,'number','min="0" step="0.01" required')}${field('Precio (MXN)','precio',p?.precio||0,'number','min="0" step="0.01" required')}</div><label class="field"><span>Foto del producto · JPG, PNG o WebP, hasta 2 MB</span><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="photo-preview">${photoValue?`<img class="image-preview" src="${e(photoValue)}" alt="Foto actual">`:''}</div><div><div class="variant-head"><h3>Tallas, tonos y existencias</h3><button type="button" class="button quiet" data-act="variant-add">+ Variante</button></div><p class="help">Talla / presentación · Color / tono · Disponibles</p><div id="variants">${(p?.v||[{t:'U',c:'Natural',s:0,ap:0}]).map((v,i)=>variantFields(v,i,!!p)).join('')}</div>${p?`<p class="help section">Las existencias se ajustan con un movimiento. Conserva tallas y tonos que ya tienen historial.</p>${button('move-open','Registrar movimiento','package',p.id,'secondary button')}`:''}</div>${formFooter()}</form>`);}
function variantFields(v,i,existing){return `<div class="variant-row" data-existing="${existing?'1':'0'}"><input aria-label="Talla o presentación ${i+1}" name="t" value="${e(v.t)}" ${existing?'readonly':''} required><input aria-label="Color o tono ${i+1}" name="c" value="${e(v.c)}" ${existing?'readonly':''} required><input aria-label="Disponibles ${i+1}" name="s" type="number" value="${v.s}" min="0" step="1" ${existing?'readonly':''} required></div>`;}
function clientForm(id){const c=cid(id);modal(c?'Editar clienta':'Agregar clienta',`<form class="form" id="client-form" data-id="${e(id||'')}">${field('Nombre','nombre',c?.nombre||'','text','required maxlength="150"')}${field('WhatsApp','tel',c?.tel||'','tel','placeholder="10 dígitos; opcional"')}<label class="field"><span>Notas</span><textarea name="nota">${e(c?.nota||'')}</textarea></label>${formFooter()}</form>`);}
function moveForm(id){const p=pid(id);if(!p)return;modal('Movimiento · '+p.nombre,`<form class="form" id="move-form" data-id="${e(id)}">${select('Variante','vi',p.v.map((v,i)=>[i,`${v.t} / ${v.c} · ${v.s} disponibles, ${v.ap} apartados`]))}${select('Movimiento','tp',['Entrada','Merma / daño','Conteo físico (ajuste)','Apartar','Entregar apartado','Liberar apartado'])}${field('Cantidad / conteo final','q',1,'number','min="0" step="1" required')}${field('Motivo','mo','','text','required minlength="3"')}<p class="help">Las reservas ligadas a ventas se entregan o cancelan desde su ticket.</p>${formFooter('Guardar movimiento')}</form>`);}
function cartAdd(id){const p=pid(id);if(!p||!qty(p))return;modal(p.nombre,`<form class="form" id="cart-add-form" data-id="${e(id)}">${imageFor(p)?`<img class="image-preview" src="${e(imageFor(p))}" alt="${e(p.nombre)}">`:''}${select('Talla o tono','vi',p.v.map((v,i)=>[i,`${v.t} / ${v.c} · ${v.s} disponibles`]))}${field('Cantidad','q',1,'number','min="1" step="1" required')}<p class="help">${mx(p.precio)} por pieza</p>${formFooter('Agregar a la venta')}</form>`);}
function search(q=''){const match=s=>String(s).toLowerCase().includes(q.toLowerCase());const ps=db.daya_productos.filter(p=>match(p.nombre+' '+p.sku+' '+p.brand)).slice(0,5),cs=db.daya_clientes.filter(c=>match(c.nombre+' '+c.tel)).slice(0,5),vs=db.daya_ventas.filter(v=>match(folio(v)+' '+customer(v))).slice(-5).reverse();return q?`<h3>Productos</h3>${ps.map(p=>`<a class="row-item" href="#inventario" data-act="search-product" data-id="${e(p.id)}">${imageFor(p)?`<img class="thumb" src="${e(imageFor(p))}" alt="">`:''}<span class="grow"><strong>${e(p.nombre)}</strong><small>${e(p.sku)}</small></span><strong>${mx(p.precio)}</strong></a>`).join('')||'<p class="help">Sin coincidencias.</p>'}<h3>Clientas</h3>${cs.map(c=>`<a class="row-item" href="#cliente/${e(c.id)}"><span class="grow">${e(c.nombre)}</span>${icon('chevron-right')}</a>`).join('')||'<p class="help">Sin coincidencias.</p>'}<h3>Ventas</h3>${vs.map(v=>`<a class="row-item" href="#ticket/${e(v.id)}"><span class="grow">${e(folio(v)+' · '+customer(v))}</span><strong>${mx(Daya.total(v))}</strong></a>`).join('')||'<p class="help">Sin coincidencias.</p>'}`:'<p class="help section">Busca por nombre, código, marca o folio.</p>';}
async function loadUsers(){if(review){$('#users-list').innerHTML='<p class="help">Las cuentas se administran al iniciar sesión en tu tienda.</p>';return;}try{const users=await api('/api/users');if(!$('#users-list'))return;$('#users-list').innerHTML=users.map(u=>`<div class="row-item"><div class="avatar">${e(initials(u.nombre))}</div><div class="grow"><strong>${e(u.nombre)}</strong><small>${e(u.email)} · ${u.rol==='d'?'Dueña':'Vendedora'} · ${u.activo?'Activa':'Desactivada'}</small></div>${u.id!==user.id?button('user-toggle',u.activo?'Desactivar':'Activar','',u.id,'quiet button'):''}</div>`).join('');}catch(err){toast(err.message);}}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function backup(){if(review)throw Error('Inicia la tienda para descargar su respaldo.');const b=await api('/api/backup');download(`Daya-${today()}.json`,JSON.stringify(b,null,2),'application/json');}
function exportCSV(){const quoted=x=>'"'+String(x??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';const rows=[['Folio','Fecha','Clienta','Estado','Total','Abonado','Saldo'],...db.daya_ventas.filter(v=>route()==='reportes'?v.fecha>=reportFrom&&v.fecha<=reportTo:true).map(v=>[folio(v),v.fecha,customer(v),v.estado,Daya.total(v),Daya.paid(v),Daya.balance(v)])];download(`Daya-ventas-${today()}.csv`,'\uFEFF'+rows.map(r=>r.map(quoted).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
async function shareText(title,text){if(navigator.share){try{await navigator.share({title,text});}catch(err){if(err.name!=='AbortError')throw err;}}else if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast('Detalle copiado para compartir.');}else{download('Daya-ticket.txt',text);toast('Detalle preparado para compartir.');}}
function whatsapp(text,tel){const number=Daya.phone(tel);const a=document.createElement('a');a.href='https://wa.me/'+number+'?text='+encodeURIComponent(text);a.target='_blank';a.rel='noopener noreferrer';a.click();}
function authView(setup,resetToken=''){const recovery=route()==='recuperar';$('#app').innerHTML=`<div class="auth"><section class="auth-story">${brand()}<div><h2>Lo bonito<br>de tener<br>todo en orden.</h2><p>Tu ropa, tus favoritos de belleza y cada venta, en un solo lugar.</p></div><img src="/Dayas/gestion/assets/vestido.jpg" alt="Fotografía de moda, referencia visual"><span class="story-footer">Daya Clothing · Hecho para tu día a día.</span></section><main class="auth-body" id="main" tabindex="-1"><div class="auth-card"><div class="auth-brand-mobile">${brand()}</div><h1>${resetToken?'Recupera tu espacio.':setup?'Bienvenida a Daya.':recovery?'Volvamos a tu tienda.':'Qué gusto verte.'}</h1><p>${resetToken?'Elige una contraseña nueva para tu cuenta.':setup?'Configura la cuenta de la dueña. Después podrás agregar a tu equipo.':recovery?'Escribe el correo de tu cuenta para recibir un enlace de recuperación.':'Inicia sesión para continuar con tu tienda.'}</p><form class="form" id="${resetToken?'reset':setup?'setup':recovery?'recover':'login'}-form" data-token="${e(resetToken)}">${setup?field('Tu nombre','nombre','','text','required autocomplete="name"'):''}${!resetToken?field('Correo electrónico','email','','email','required autocomplete="username"'):''}${!recovery||resetToken?field(setup||resetToken?'Contraseña · mínimo 12 caracteres':'Contraseña','password','','password',`required ${setup||resetToken?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"'} maxlength="128"`):''}<div class="form-error" role="alert"></div><button class="primary full">${resetToken?'Guardar contraseña':setup?'Crear mi tienda':recovery?'Enviar enlace':'Entrar a mi tienda'}</button></form><div class="auth-explore section"><a href="/Dayas/gestion/?revision=1">Explorar el panel · Solo lectura ↗</a><a href="/Dayas/tienda.html">Volver a la tienda ↗</a></div><div class="auth-links">${!setup?`<a href="#${recovery||resetToken?'acceso':'recuperar'}">${recovery||resetToken?'Volver al acceso':'Olvidé mi contraseña'}</a>`:''}</div><p class="help section">${setup?'Los datos se guardarán en la base de datos de Daya en Supabase. El correo identifica tu cuenta; crearlo aquí no crea un buzón Gmail.':'La conexión con el servidor es necesaria para guardar operaciones.'}</p></div></main></div>`;}
const actions={
 close, 'product-new':()=>productForm(), 'product-edit':id=>productForm(id),'client-new':()=>clientForm(),'client-edit':id=>clientForm(id),'move-open':id=>{close();moveForm(id);},'cart-add':cartAdd,
 'variant-add':()=>{const list=$('#variants'),i=list.children.length;list.insertAdjacentHTML('beforeend',variantFields({t:'',c:'',s:0},i,false));},
 'cart-plus':id=>{const i=cart[+id],p=pid(i.pid);if(i.q>=p.v[i.vi].s)throw Error('No hay más piezas disponibles de esta variante.');i.q++;renderCart();$('#cart [data-act=cart-plus][data-id="'+id+'"]')?.focus({preventScroll:true});},'cart-minus':id=>{const i=cart[+id];if(--i.q===0)cart.splice(+id,1);renderCart();$('#cart [data-act=cart-minus][data-id="'+Math.min(+id,cart.length-1)+'"]')?.focus({preventScroll:true});},
 category:id=>{category=id;renderKeepingFocus();},'sale-filter':id=>{saleFilter=id;renderKeepingFocus();},'inventory-view':id=>{inventoryView=id;renderKeepingFocus();},'cart-jump':()=>{$('#cart')?.scrollIntoView({block:'start',behavior:'instant'});$('#cart h2')?.setAttribute('tabindex','-1');$('#cart h2')?.focus({preventScroll:true});},export:exportCSV,backup,
 search:()=>modal('Encuentra lo que necesitas',`<label class="field"><span>Buscar en tu tienda</span><input type="search" id="global-search" placeholder="Nombre, producto o folio…" autocomplete="off"></label><div class="search-results" id="search-results">${search()}</div>`),
 'search-product':id=>{close();if(owner())productForm(id);else location.hash='catalogo';},
 print:()=>{document.documentElement.style.setProperty('--thermal-width',($('select[name=thermal]')?.value||'80')+'mm');window.print();},
 whatsapp:id=>{const v=sale(id),c=cid(v.cid);if(!c?.tel)throw Error('Agrega el WhatsApp de la clienta para enviar el ticket.');whatsapp(Daya.ticket(db,v),c.tel);},
 share:id=>shareText('Ticket Daya '+folio(sale(id)),Daya.ticket(db,sale(id))),
 want:id=>{const p=pid(id);if(!db.daya_cfg.tel)throw Error('Guarda el WhatsApp de la tienda en Ajustes.');whatsapp(`Hola, me interesa ${p.nombre} (${p.sku}) de ${mx(p.precio)}. ¿Me compartes las variantes disponibles?`,db.daya_cfg.tel);},
 'share-catalog':()=>shareText('Catálogo de Daya Clothing',['DAYA CLOTHING',...db.daya_productos.filter(p=>qty(p)>0).map(p=>`${p.nombre} · ${p.sku} · ${mx(p.precio)}`),db.daya_cfg.tel?'WhatsApp: '+db.daya_cfg.tel:''].join('\n')),
 remind:id=>{const v=sale(id),c=cid(v.cid);if(!c?.tel)throw Error('Agrega el WhatsApp de la clienta para preparar el aviso.');const msg=db.daya_cfg.msg.replaceAll('{nombre}',c.nombre).replaceAll('{saldo}',mx(Daya.balance(v))).replaceAll('{folio}',folio(v)).replaceAll('{fecha}',v.limite?date(v.limite):'sin fecha límite');modal('Preparar recordatorio',`<p class="help">Se abrirá WhatsApp con este texto. Tú decides cuándo enviarlo.</p><p class="section">${e(msg)}</p><form class="form section" id="remind-form" data-id="${e(id)}"><div class="form-error" role="alert"></div><button class="primary">Abrir WhatsApp y registrar aviso preparado</button></form>`);},
 deliver:id=>modal('Confirmar entrega',`<p>Se descontarán las piezas apartadas de ${e(folio(sale(id)))}. La cuenta ya debe estar liquidada.</p><form id="deliver-form" class="form section" data-id="${e(id)}">${formFooter('Confirmar entrega')}</form>`),
 cancel:id=>modal('Cancelar '+folio(sale(id)),`<p class="help">Los abonos se conservarán en el ticket. La devolución de dinero se registra por separado en Caja.</p><form id="cancel-form" class="form section" data-id="${e(id)}">${sale(id).stockMode==='entregado'?'<label><input type="checkbox" name="returned"> Recibí los productos y deben volver al inventario</label>':'<p>Las piezas reservadas se liberarán.</p>'}${formFooter('Cancelar venta')}</form>`),
 void:(id,el)=>{const a=sale(id)?.abonos.find(a=>a.id===el.dataset.payment);if(!a)throw Error('El pago cambió; vuelve a abrir el ticket.');modal('Anular abono de '+mx(a.m),`<p class="help">${db.daya_cortes.some(c=>c.f===a.f)?'El corte original se conserva y se registrará una salida en la caja de hoy.':'El abono quedará anulado y recuperará el saldo correspondiente.'}</p><form class="form section" id="void-form" data-id="${e(id)}" data-payment="${e(a.id)}">${field('Motivo','reason','','text','required minlength="3"')}${formFooter('Confirmar anulación')}</form>`);},
 'cash-new':()=>modal('Movimiento de caja',`<form class="form" id="cash-form">${select('Tipo','tipo',['Egreso','Ingreso'])}${select('Categoría','cat',['Compra de mercancía','Renta','Bolsas y empaque','Transporte','Retiro del dueño','Otro','Venta','Abono'])}${field('Concepto','desc','','text','required')}${field('Monto (MXN)','m','','number','min="0.01" step="0.01" required')}${methods()}<p class="help">Las ventas y abonos ya aparecen automáticamente; no los registres de nuevo.</p>${formFooter()}</form>`),
 period:id=>{reportTo=today();reportFrom=id==='day'?today():id==='week'?offset(-6):id==='year'?today().slice(0,4)+'-01-01':today().slice(0,8)+'01';render();},
 'user-new':()=>modal('Agregar persona',`<form class="form" id="user-form">${field('Nombre','nombre','','text','required')}${field('Correo de acceso','email','','email','required autocomplete="off"')}${select('Perfil','rol',[['v','Vendedora · Cobranza, catálogo y tickets'],['d','Dueña · Acceso completo']])}${field('Contraseña inicial','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="help">Este acceso pertenece a Daya. No crea una cuenta de Google.</p>${formFooter('Crear acceso')}</form>`),
 'user-toggle':id=>modal('Cambiar estado de la cuenta',`<p>Desactivar revoca todas sus sesiones abiertas en el servidor.</p><form class="form section" id="user-toggle-form" data-id="${e(id)}">${formFooter('Confirmar cambio')}</form>`),
 'mail-preview':async()=>{if(review)throw Error('La vista de correos requiere iniciar sesión en la tienda.');const m=await api('/api/mail/preview');modal('Así se verá tu correo','<iframe class="email-preview" sandbox="" title="Vista previa del correo"></iframe>');$('.email-preview').srcdoc=m.html;},
 'mail-test':async()=>{if(review)throw Error('Inicia sesión y configura el correo de la tienda.');const r=await api('/api/mail/test',{method:'POST',body:'{}'});toast(r.state==='enviado'?'Correo aceptado por SMTP. Revisa el buzón de la tienda.':'Correo no enviado.');},
 'mail-ticket':async id=>{const r=await api('/api/mail/ticket',{method:'POST',body:JSON.stringify({saleId:id})});toast(r.state==='enviado'?'Copia aceptada por SMTP. Revisa el buzón de la tienda.':'Correo no enviado.');},
 'mail-log':async()=>{const list=await api('/api/mail');modal('Estado de los correos',list.length?list.map(m=>`<div class="row-item"><div class="grow"><strong>${e(m.subject)}</strong><small>${e(m.recipient)} · ${e(m.created)}${m.error?' · '+e(m.error):''}</small></div><span class="badge">${e(m.state)}</span></div>`).join(''):'<p class="help">Aún no se han intentado envíos.</p>');},
 sample:()=>modal('Cargar colección de ejemplo',`<p>Agrega productos con fotografías, clientas y operaciones ficticias a esta tienda vacía. Podrás explorar todos los flujos.</p><form class="form section" id="sample-form">${formFooter('Cargar ejemplos')}</form>`),
 logout:async()=>{if(review){location.href='/Dayas/gestion/';return;}await api('/api/auth/logout',{method:'POST',body:'{}'});user=null;csrf='';cart=[];location.hash='acceso';authView(false);toast('Sesión cerrada.');}
};
document.addEventListener('click',async ev=>{if(ev.target.closest('.skip')){ev.preventDefault();$('#main')?.focus();return;}const el=ev.target.closest('[data-act]');if(el){ev.preventDefault();if(busy||el.getAttribute('aria-busy')==='true')return;const label=el.innerHTML;try{const result=actions[el.dataset.act]?.(el.dataset.id,el);if(result&&typeof result.then==='function'){el.setAttribute('aria-busy','true');el.disabled=true;el.textContent='Preparando…';await result;}}catch(err){toast(err.message);}finally{if(el.isConnected&&el.getAttribute('aria-busy')==='true'){el.removeAttribute('aria-busy');el.disabled=false;el.innerHTML=label;}}}else if(ev.target.closest('dialog a[href^="#"]'))close();});
document.addEventListener('input',ev=>{const t=ev.target;if(t.id==='product-search'){query=t.value;$('#products').innerHTML=productCards(route()==='vender'?'pos':route()==='catalogo'?'catalog':'inventory');}if(t.id==='client-search')$('#client-list').innerHTML=clientRows(t.value);if(t.id==='global-search')$('#search-results').innerHTML=search(t.value);if(t.name==='desc'&&$('#cart-total'))$('#cart-total').textContent=mx(Math.max(0,sum(cart.map(i=>i.p*i.q))-Number(t.value||0)));});
document.addEventListener('change',async ev=>{const t=ev.target;try{if(t.id==='stock-filter'){stockFilter=t.value;$('#products').innerHTML=productCards();}if(t.name==='tipo'&&t.closest('#sale-form'))$('#installment-fields').classList.toggle('hide',t.value!=='apartado');if(t.name==='report-from'||t.name==='report-to'){const f=$('[name=report-from]').value,to=$('[name=report-to]').value;if(!Daya.validDate(f)||!Daya.validDate(to)||f>to)throw Error('Elige un periodo válido.');reportFrom=f;reportTo=to;render();}if(t.name==='cash-date'){cashDate=t.value;render();}if(t.id==='photo-file'&&t.files[0]){const f=t.files[0];if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2*1024*1024)throw Error('Elige una imagen JPG, PNG o WebP de hasta 2 MB.');photoValue=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});$('#photo-preview').innerHTML=`<img class="image-preview" src="${e(photoValue)}" alt="Foto seleccionada">`;}if(t.id==='import-file'&&t.files[0]){const f=t.files[0];if(f.size>20*1024*1024)throw Error('El respaldo supera 20 MB.');const parsed=Daya.parseBackup(await f.text());modal('Restaurar respaldo',`<p>Reemplazará los datos de negocio por ${parsed.daya_productos.length} productos, ${parsed.daya_clientes.length} clientas y ${parsed.daya_ventas.length} ventas. Las cuentas de acceso del servidor se conservan.</p><form class="form section" id="import-form">${formFooter('Restaurar datos')}</form>`);$('#import-form').backup=parsed;}}catch(err){toast(err.message);}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target;if(!(f instanceof HTMLFormElement)||!f.reportValidity()||busy)return;const fd=new FormData(f),v=Object.fromEntries(fd),num=k=>Number(v[k]||0),id=f.dataset.id,submit=f.querySelector('button[type=submit],button:not([type])');busy=true;f.setAttribute('aria-busy','true');const submitLabel=submit?.innerHTML,waitingLabel=['login-form','setup-form'].includes(f.id)?'Entrando…':['recover-form','remind-form'].includes(f.id)?'Preparando…':'Guardando…';if(submit){submit.disabled=true;submit.textContent=waitingLabel;}try{switch(f.id){
 case'setup-form':case'login-form':{const r=await api('/api/auth/'+(f.id==='setup-form'?'setup':'login'),{method:'POST',body:JSON.stringify(v)});if(r.pendingConfirmation){f.querySelector('.form-error').innerHTML=`<p class="notice">${e(r.message)}</p>`;break;}user=r.user;csrf=r.csrf;await refresh();location.hash=owner()?'inicio':'cobranza';render();break;}
 case'recover-form':{const r=await api('/api/auth/recover',{method:'POST',body:JSON.stringify(v)});f.querySelector('.form-error').innerHTML=`<p class="notice">${e(r.message)}</p>`;break;}
 case'reset-form':await api('/api/auth/reset',{method:'POST',body:JSON.stringify({token:f.dataset.token,password:v.password})});location.hash='acceso';authView(false);toast('Contraseña actualizada. Inicia sesión.');break;
 case'product-form':{const old=pid(id),variants=[...f.querySelectorAll('.variant-row')].map((row,i)=>({t:row.querySelector('[name=t]').value.trim(),c:row.querySelector('[name=c]').value.trim(),s:Number(row.querySelector('[name=s]').value),ap:old?.v[i]?.ap||0}));await operation('product',[{...(old||{}),id:id||undefined,nombre:v.nombre,cat:v.cat,sku:v.sku,brand:v.brand,costo:num('costo'),precio:num('precio'),min:num('min'),foto:photoValue,v:variants}]);close();render();toast('Producto guardado.');break;}
 case'client-form':await operation('client',[{id:id||undefined,...v}]);close();render();toast('Clienta guardada.');break;
 case'move-form':await operation('move',[id,num('vi'),v.tp,num('q'),v.mo]);close();render();toast('Movimiento registrado.');break;
 case'cart-add-form':{const p=pid(id),vi=num('vi'),q=num('q'),existing=cart.find(i=>i.pid===id&&i.vi===vi);if(!Number.isSafeInteger(q)||q<1||q+(existing?.q||0)>p.v[vi].s)throw Error('Revisa la cantidad disponible de esa variante.');if(existing)existing.q+=q;else cart.push({pid:id,vi,p:p.precio,q});close();renderCart();toast('Agregado a tu venta.');break;}
 case'sale-form':{if(!cart.length)throw Error('Agrega productos a la venta.');const result=await operation('sale',[{cid:v.cid,tipo:v.tipo,items:cart,desc:num('desc'),enganche:v.tipo==='apartado'?num('enganche'):0,met:v.met,limite:v.tipo==='apartado'?v.limite:''}]);cart=[];location.hash='ticket/'+result.id;render();toast('Venta registrada.');break;}
 case'pay-form':await operation('pay',[id,num('m'),v.met]);render();toast('Abono registrado.');break;
 case'deliver-form':await operation('deliver',[id]);close();render();toast('Entrega registrada.');break;
 case'cancel-form':await operation('cancel',[id,fd.has('returned')]);close();render();toast('Venta cancelada; historial conservado.');break;
 case'void-form':await operation('voidPayment',[id,f.dataset.payment,v.reason]);close();render();toast('Abono anulado.');break;
 case'opening-form':await operation('opening',[cashDate,num('m')]);render();toast('Apertura guardada.');break;
 case'cash-form':await operation('cash',[{...v,f:cashDate,m:num('m')}]);close();render();toast('Movimiento de caja guardado.');break;
 case'cut-form':{const n=num('m'),s=Daya.cashSummary(db,cashDate);modal('Revisar corte de caja',`<p>Esperado: <strong>${mx(s.esp)}</strong><br>Contado: <strong>${mx(n)}</strong><br>Diferencia: <strong>${mx(n-s.esp)}</strong></p><p class="help section">El corte quedará guardado sin posibilidad de sobrescribirlo.</p><form class="form section" id="cut-confirm-form" data-count="${n}" data-date="${e(cashDate)}">${formFooter('Guardar corte')}</form>`);break;}
 case'cut-confirm-form':await operation('close',[f.dataset.date,Number(f.dataset.count)]);close();render();toast('Corte guardado.');if(db.daya_cfg.autoBackup)await backup();break;
 case'settings-form':await operation('settings',[{...v,autoBackup:fd.has('autoBackup')}]);render();toast('Información guardada.');break;
 case'user-form':await api('/api/users',{method:'POST',body:JSON.stringify({action:'create',nombre:v.nombre,email:v.email,rol:v.rol,password:v.password})});close();await loadUsers();toast('Acceso creado.');break;
 case'user-toggle-form':await api('/api/users',{method:'POST',body:JSON.stringify({action:'toggle',id})});close();await loadUsers();toast('Estado de la cuenta actualizado.');break;
 case'sample-form':await api('/api/sample',{method:'POST',body:'{}'});await refresh();close();location.hash='inicio';render();toast('Colección de ejemplo cargada.');break;
 case'import-form':await api('/api/import',{method:'POST',body:JSON.stringify({backup:f.backup,revision})});await refresh();close();render();toast('Respaldo restaurado.');break;
 case'remind-form':{const s=sale(id),c=cid(s.cid),msg=db.daya_cfg.msg.replaceAll('{nombre}',c.nombre).replaceAll('{saldo}',mx(Daya.balance(s))).replaceAll('{folio}',folio(s)).replaceAll('{fecha}',s.limite?date(s.limite):'sin fecha límite');whatsapp(msg,c.tel);await operation('reminder',[id]);close();render();toast('Aviso preparado; confirma el envío en WhatsApp.');break;}
 default:throw Error('Formulario no disponible.');}
 }catch(err){const box=f.querySelector('.form-error');if(box&&document.contains(f)){box.innerHTML=`<p class="error" tabindex="-1">${e(err.message)}</p>`;box.querySelector('.error').focus();}else toast(err.message);}finally{busy=false;f.removeAttribute('aria-busy');if(submit&&document.contains(submit)){submit.disabled=false;submit.innerHTML=submitLabel;}}});
window.addEventListener('hashchange',()=>{close();category='Todas';query='';if(user){render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});}else authView(setupRequired,route().startsWith('restablecer/')?route().split('/')[1]:'');});
window.addEventListener('offline',()=>{updateConnection();toast('Sin conexión. Conserva esta pantalla y vuelve a intentar cuando tengas internet.');});
window.addEventListener('online',()=>{updateConnection();toast('Conexión restablecida. Ya puedes volver a intentar la operación.');});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'&&user&&!busy&&!$('#modal').open){ev.preventDefault();actions.search();}});
document.addEventListener('visibilitychange',async()=>{if(!document.hidden&&user&&!review&&!$('#modal').open&&!busy&&!document.querySelector('form')&&!cart.length){try{await refresh();render();}catch(err){toast(err.message);}}});
async function boot(){try{await globalThis.DAYA_AUTH_READY;if(route()==='vistaprevia'||new URLSearchParams(location.search).has('revision')){const r=await api('/api/review');db=r.data;revision=r.revision;user=r.user;sample=true;review=true;render();return;}const s=await api('/api/auth/status');smtp=s.smtp;setupRequired=s.setup;csrf=s.csrf||'';if(route().startsWith('restablecer/'))return authView(false,route().split('/')[1]);if(s.user){user=s.user;csrf=s.csrf;await refresh();if(['acceso','recuperar'].includes(route()))location.hash=owner()?'inicio':'cobranza';render();}else authView(s.setup);}catch(err){$('#app').innerHTML=`<main class="auth-body" id="main" tabindex="-1"><div class="auth-card"><div class="error-brand">${brand()}</div><h1>No pudimos abrir tu tienda.</h1><p>Revisa tu conexión e intenta de nuevo. Tus datos guardados siguen en tu tienda.</p><p class="error" role="alert">${e(err.message)}</p><button class="primary full" data-act="retry">Volver a intentar</button><div class="auth-explore section"><a href="/Dayas/gestion/?revision=1">Explorar el panel · Solo lectura ↗</a><a href="/Dayas/tienda.html">Volver a la tienda ↗</a></div></div></main>`;}if('serviceWorker'in navigator)navigator.serviceWorker.register('/Dayas/gestion/sw.js').catch(()=>{});}
actions.retry=()=>location.reload();boot();
})();
